function appendix(t,s=1,inf=0){const col=inf>0.5?'#E8505B':'#F3A6B5';const sw=1+0.25*inf;return g(`scale(${s})`,`<path d="M-260,-200Q-300,-60 -220,40Q-160,110 -40,90Q80,70 160,120" stroke="#E9A58C" stroke-width="110" fill="none" stroke-linecap="round"/><path d="M-260,-200Q-300,-60 -220,40Q-160,110 -40,90Q80,70 160,120" stroke="${OL}" stroke-width="6" fill="none" opacity=".25"/>${g(`translate(-230,70) rotate(${fmt(20+3*Math.sin(t*3)*inf)}) scale(${fmt(sw)},${fmt(sw)})`,`<path d="M-30,0C-40,80 -20,170 10,200C40,220 50,190 40,150C30,90 30,40 30,0Z" fill="${col}" stroke="${OL}" stroke-width="6"/>`)}${inf>0.5?`<path d="M-300,240l-30,-20M-190,280l20,-30M-320,170l-40,0" stroke="#E5383B" stroke-width="10" stroke-linecap="round" opacity="${fmt(0.5+0.5*Math.sin(t*8))}"/>`:''}`);}
function poopLump(s=1){return g(`scale(${s})`,`<ellipse cx="0" cy="20" rx="70" ry="34" fill="#8A5A3B" stroke="${OL}" stroke-width="5"/><ellipse cx="0" cy="-14" rx="50" ry="28" fill="#9B6A48" stroke="${OL}" stroke-width="5"/><ellipse cx="0" cy="-42" rx="28" ry="18" fill="#A87752" stroke="${OL}" stroke-width="5"/>`);}
function broccoli(s=1){return g(`scale(${s})`,`<path d="M-24,40L-30,150L30,150L24,40Z" fill="#9CD08A" stroke="${OL}" stroke-width="6"/>`+[[-60,-10],[0,-50],[60,-10],[-30,30],[30,30],[0,0]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="52" fill="#3BB273" stroke="${OL}" stroke-width="6"/>`).join(''));}
function rainCloud(t,s=1,rain=true){let d='';if(rain)for(let i=0;i<8;i++){const ph=(t*1.4+i*0.37)%1;d+=`<path d="M${-150+i*42},${fmt(80+ph*260)}l-10,30" stroke="#5DB7EA" stroke-width="10" stroke-linecap="round" opacity="${fmt(1-ph)}"/>`;}return g(`scale(${s})`,d+`<path d="M-180,60C-240,60 -240,-20 -180,-30C-180,-110 -80,-130 -40,-70C0,-140 120,-120 120,-40C200,-50 210,60 140,60Z" fill="#C9D3E0" stroke="${OL}" stroke-width="7"/><circle cx="-50" cy="0" r="9" fill="#2E2430"/><circle cx="20" cy="0" r="9" fill="#2E2430"/><path d="M-30,30Q-15,22 0,30" stroke="#2E2430" stroke-width="5" fill="none"/>`);}
function umbrella(s=1,col='#E8505B'){return g(`scale(${s})`,`<path d="M-220,0Q-220,-200 0,-210Q220,-200 220,0Q180,-30 145,0Q110,-30 73,0Q36,-30 0,0Q-36,-30 -73,0Q-110,-30 -145,0Q-180,-30 -220,0Z" fill="${col}" stroke="${OL}" stroke-width="7" stroke-linejoin="round"/><path d="M0,-210L0,230Q0,270 -40,270Q-70,270 -70,240" stroke="${OL}" stroke-width="12" fill="none" stroke-linecap="round"/>`);}
function virus(t,s=1,col='#7BC96F'){let sp='';for(let i=0;i<10;i++){const a=i*36+t*25;sp+=`<g transform="rotate(${fmt(a)})"><path d="M0,-70L0,-110" stroke="${OL}" stroke-width="8"/><circle cx="0" cy="-116" r="16" fill="${col}" stroke="${OL}" stroke-width="5"/></g>`;}return g(`scale(${s})`,sp+`<circle r="76" fill="${col}" stroke="${OL}" stroke-width="7"/><path d="M-36,-14L-14,-4M36,-14L14,-4" stroke="#2E2430" stroke-width="7" stroke-linecap="round"/><circle cx="-24" cy="6" r="8" fill="#2E2430"/><circle cx="24" cy="6" r="8" fill="#2E2430"/><path d="M-22,40Q0,26 22,40" stroke="#2E2430" stroke-width="6" fill="none"/>`);}
function footBucket(t,s=1){return g(`scale(${s})`,`<path d="M-70,-260L-60,-20L60,-20L70,-260Z" fill="#F3C9A8" stroke="${OL}" stroke-width="6"/><path d="M-170,-40L-140,200L140,200L170,-40Z" fill="#5B6C8F" stroke="${OL}" stroke-width="7"/><path d="M-160,10Q-80,${fmt(-6+8*Math.sin(t*3))} 0,10T160,10L150,40L-150,40Z" fill="#9FD8F2" opacity=".9"/>${g("translate(120,-130) scale(1.6)",snowflake())}`);}
function nose(t,s=1,narrow=0){const w=lerp(26,10,narrow);return g(`scale(${s})`,`<path d="M-30,-200C-40,-80 -150,40 -110,110C-80,150 -20,130 0,120C20,130 80,150 110,110C150,40 40,-80 30,-200Z" fill="#F3C9A8" stroke="${OL}" stroke-width="7" stroke-linejoin="round"/><ellipse cx="-50" cy="100" rx="${fmt(w)}" ry="16" fill="#8E3B4F"/><ellipse cx="50" cy="100" rx="${fmt(w)}" ry="16" fill="#8E3B4F"/><path d="M-60,-40Q0,${fmt(-20+30*narrow)} 60,-40" stroke="#E5383B" stroke-width="${fmt(lerp(14,5,narrow))}" fill="none" stroke-linecap="round"/>`);}
