function rocketShip(t,s=1){const f=20+10*Math.sin(t*20);return g(`scale(${s})`,`<path d="M0,-160C60,-100 60,40 40,90L-40,90C-60,40 -60,-100 0,-160Z" fill="#fff" stroke="${OL}" stroke-width="7"/><circle cy="-50" r="26" fill="#2C8FC4" stroke="${OL}" stroke-width="6"/><path d="M-40,40L-80,110L-40,90Z M40,40L80,110L40,90Z" fill="#E5383B" stroke="${OL}" stroke-width="6"/><path d="M-25,90L0,${fmt(90+f*3)}L25,90Z" fill="#F2A541"/>`);}
function walker(t,s=1,o={}){const w=o.walk?Math.sin(t*5):0;return g(`scale(${s})`,`<path d="M-20,120L${fmt(-20-w*30)},260M20,120L${fmt(20+w*30)},260" stroke="#2C4A7A" stroke-width="34" stroke-linecap="round"/><rect x="-60" y="-60" width="120" height="190" rx="40" fill="#F2F2F2" stroke="${OL}" stroke-width="7"/>${[0,1,2].map(i=>`<path d="M-60,${-20+i*50}L60,${-20+i*50}" stroke="#8FB3E0" stroke-width="12"/>`).join('')}<path d="M-55,-20L-150,-30M55,-20L150,-30" stroke="#F2C9A0" stroke-width="28" stroke-linecap="round"/><circle cy="-120" r="70" fill="#F2C9A0" stroke="${OL}" stroke-width="7"/>${o.awake?`<circle cx="-24" cy="-125" r="12" fill="${OL}"/><circle cx="24" cy="-125" r="12" fill="${OL}"/><path d="M-12,-85Q0,-75 12,-85" stroke="${OL}" stroke-width="6" fill="none"/>`:`<path d="M-38,-125Q-24,-115 -10,-125M10,-125Q24,-115 38,-125" stroke="${OL}" stroke-width="6" fill="none" stroke-linecap="round"/>`}`);}
