function chameleon(t,s=1,col='#7BC96F'){return g(`scale(${s})`,`<path d="M120,40C200,40 220,140 160,150C120,155 120,110 150,110" stroke="${col}" stroke-width="30" fill="none" stroke-linecap="round"/><ellipse cx="0" cy="20" rx="150" ry="85" fill="${col}" stroke="${OL}" stroke-width="7"/><path d="M-110,-40L-60,-80L-10,-50L40,-80L90,-50" stroke="${OL}" stroke-width="6" fill="none" opacity=".4"/>${[-80,60].map(x=>`<path d="M${x},90L${x-10},150L${x+20},150" stroke="${col}" stroke-width="24" fill="none" stroke-linecap="round"/>`).join('')}<path d="M-140,-20C-220,-40 -250,30 -200,70C-170,90 -140,60 -140,40Z" fill="${col}" stroke="${OL}" stroke-width="7"/><circle cx="-180" cy="10" r="30" fill="#fff" stroke="${OL}" stroke-width="5"/><circle cx="${fmt(-185+6*Math.sin(t*2))}" cy="10" r="12" fill="${OL}"/>`);}
function bat(t,s=1){const f=Math.sin(t*12)*25;return g(`scale(${s})`,`<path d="M-30,0C-90,${fmt(-60-f)} -170,${fmt(-50-f)} -220,${fmt(-10-f)}C-180,${fmt(10-f*0.5)} -170,30 -150,50C-120,30 -100,40 -80,60C-60,40 -40,40 -30,30Z" fill="#4A3D5C" stroke="${OL}" stroke-width="6"/><path d="M30,0C90,${fmt(-60-f)} 170,${fmt(-50-f)} 220,${fmt(-10-f)}C180,${fmt(10-f*0.5)} 170,30 150,50C120,30 100,40 80,60C60,40 40,40 30,30Z" fill="#4A3D5C" stroke="${OL}" stroke-width="6"/><ellipse cy="20" rx="50" ry="60" fill="#5E4E73" stroke="${OL}" stroke-width="6"/><path d="M-35,-25L-45,-75L-12,-40Z M35,-25L45,-75L12,-40Z" fill="#5E4E73" stroke="${OL}" stroke-width="5"/><circle cx="-18" cy="5" r="12" fill="#fff"/><circle cx="18" cy="5" r="12" fill="#fff"/><circle cx="-18" cy="7" r="6" fill="${OL}"/><circle cx="18" cy="7" r="6" fill="${OL}"/><path d="M-10,35L-5,45L0,35L5,45L10,35" stroke="#fff" stroke-width="4" fill="none"/>`);}
function soundWaves(t,s=1){let w='';for(let i=0;i<3;i++){const ph=(t*1.2+i/3)%1;w+=`<path d="M${fmt(40+ph*200)},-${fmt(40+ph*120)}Q${fmt(80+ph*240)},0 ${fmt(40+ph*200)},${fmt(40+ph*120)}" stroke="#7FD1FF" stroke-width="10" fill="none" stroke-linecap="round" opacity="${fmt(1-ph)}"/>`;}return g(`scale(${s})`,w);}
function mosquito(t,s=1,o={}){const f=Math.sin(t*40)*18;return g(`scale(${s})`,`<path d="M-10,-10C-60,${fmt(-90-f)} -150,${fmt(-80-f)} -120,${fmt(-30-f*0.3)}C-90,-10 -40,-5 -10,0Z" fill="#DDEEFF" opacity=".75" stroke="${OL}" stroke-width="4"/><path d="M10,-10C60,${fmt(-90-f)} 150,${fmt(-80-f)} 120,${fmt(-30-f*0.3)}C90,-10 40,-5 10,0Z" fill="#DDEEFF" opacity=".75" stroke="${OL}" stroke-width="4"/>
 ${[-30,0,30].map(x=>`<path d="M${x},20L${x*2.2},90L${x*2.6},130" stroke="${OL}" stroke-width="5" fill="none" stroke-linecap="round"/>`).join('')}
 <ellipse cx="0" cy="30" rx="26" ry="70" fill="#4A4A5C" stroke="${OL}" stroke-width="5" transform="rotate(-10)"/>${[0,1,2].map(i=>`<path d="M-22,${45+i*22}L22,${40+i*22}" stroke="#E9E9F2" stroke-width="5"/>`).join('')}
 <circle cx="-8" cy="-40" r="34" fill="#4A4A5C" stroke="${OL}" stroke-width="5"/><circle cx="-22" cy="-46" r="11" fill="#fff"/><circle cx="6" cy="-46" r="11" fill="#fff"/><circle cx="-22" cy="-44" r="5" fill="${OL}"/><circle cx="6" cy="-44" r="5" fill="${OL}"/>
 <path d="M-12,-15L-30,60" stroke="${OL}" stroke-width="5" stroke-linecap="round"/>${o.evil?'<path d="M-36,-62L-12,-54M20,-62L-2,-54" stroke="#000" stroke-width="5" stroke-linecap="round"/>':''}`);}
