function bloodDrop(s=1,lbl=''){return g(`scale(${s})`,`<path d="M0,-110C40,-50 80,0 80,40C80,90 40,120 0,120C-40,120 -80,90 -80,40C-80,0 -40,-50 0,-110Z" fill="#E5383B" stroke="${OL}" stroke-width="7"/><ellipse cx="-30" cy="20" rx="14" ry="26" fill="#fff" opacity=".45"/>${lbl?`<text y="75" text-anchor="middle" font-family="Inter" font-weight="800" font-size="70" fill="#fff">${lbl}</text>`:''}`);}
