function sweatFace(t,s=1){return g(`scale(${s})`,`<circle r="120" fill="#F2C9A0" stroke="${OL}" stroke-width="7"/><circle cx="-40" cy="-15" r="12" fill="${OL}"/><circle cx="40" cy="-15" r="12" fill="${OL}"/><path d="M-35,45Q0,70 35,45" stroke="${OL}" stroke-width="7" fill="none" stroke-linecap="round"/>${[0,1].map(i=>`<path d="M${90+i*20},${fmt(-60+((t*60+i*40)%80))}c8,14 8,24 0,26c-8,-2 -8,-12 0,-26Z" fill="#7FD1FF" stroke="${OL}" stroke-width="3"/>`).join('')}`);}
