function follicle(t,s=1,o={}){const hc=o.grey?'#E9E9F2':'#2E2430';return g(`scale(${s})`,`<rect x="-260" y="-20" width="520" height="260" rx="30" fill="#F2C9A0" stroke="${OL}" stroke-width="7"/><path d="M-260,40L260,40" stroke="#E3A982" stroke-width="5"/><path d="M-40,40C-50,140 -30,190 0,200C30,190 50,140 40,40Z" fill="#E8A58C" stroke="${OL}" stroke-width="6"/><circle cy="175" r="26" fill="${o.dmg?'#9AA9B8':'#C96B5A'}" stroke="${OL}" stroke-width="5"/>${o.noHair?'':`<g transform="translate(0,160)">${hairStrand(t,1,hc,o.len||420)}</g>`}${o.pig!=null?Array.from({length:6},(_,i)=>`<circle cx="${-24+(i%3)*24}" cy="${120+Math.floor(i/3)*24}" r="9" fill="#6B4A2B" opacity="${fmt(o.pig)}"/>`).join(''):''}`);}
