function shark(t,s=1,o={}){const sw=Math.sin(t*3)*10;return g(`scale(${s}) rotate(${fmt(sw*0.3)})`,`<path d="M-300,0C-200,-110 120,-120 260,-20C200,0 200,0 260,20C120,110 -200,100 -300,0Z" fill="#7E93A8" stroke="${OL}" stroke-width="8"/><path d="M-300,0C-200,60 120,70 260,20C120,90 -200,80 -300,0Z" fill="#E6EDF2"/><path d="M-40,-90L20,-210L60,-85Z" fill="#7E93A8" stroke="${OL}" stroke-width="7" stroke-linejoin="round"/><path d="M240,-10L${fmt(340+sw)},-110L${fmt(320+sw)},0L${fmt(340+sw)},110L240,10Z" fill="#7E93A8" stroke="${OL}" stroke-width="7" stroke-linejoin="round"/><path d="M-40,30L-80,110L0,50Z" fill="#7E93A8" stroke="${OL}" stroke-width="6"/><circle cx="-200" cy="-20" r="14" fill="${OL}"/><circle cx="-205" cy="-25" r="5" fill="#fff"/><path d="M-280,20Q-240,35 -200,25" stroke="${OL}" stroke-width="6" fill="none"/>${[0,1,2].map(i=>`<path d="M${-150+i*22},-30L${-150+i*22},20" stroke="${OL}" stroke-width="4" opacity=".5"/>`).join('')}${o.tumor?`<circle cx="40" cy="-30" r="34" fill="#C96B5A" stroke="${OL}" stroke-width="5"/><circle cx="30" cy="-38" r="8" fill="#E39A8C"/>`:''}`);}
function pillBottle(s=1,lbl=''){return g(`scale(${s})`,`<rect x="-70" y="-90" width="140" height="210" rx="20" fill="#F2A541" stroke="${OL}" stroke-width="7"/><rect x="-80" y="-140" width="160" height="55" rx="10" fill="#fff" stroke="${OL}" stroke-width="6"/><rect x="-55" y="-30" width="110" height="90" rx="10" fill="#fff"/><text y="25" text-anchor="middle" font-family="Inter" font-weight="800" font-size="34" fill="${OL}">${lbl}</text>`);}
function sock(s=1,col='#E8505B',r=0){return g(`scale(${s}) rotate(${r})`,`<path d="M-50,-180L50,-180L50,40C50,90 90,100 130,110C180,122 180,190 120,195L-20,190C-60,188 -60,150 -50,120Z" fill="${col}" stroke="${OL}" stroke-width="7" stroke-linejoin="round"/><rect x="-50" y="-180" width="100" height="40" fill="#fff" stroke="${OL}" stroke-width="6"/>${[0,1].map(i=>`<path d="M-50,${-100+i*50}L50,${-100+i*50}" stroke="#fff" stroke-width="12" opacity=".7"/>`).join('')}`);}
function footWarm(t,s=1,o={}){const glow=o.warm?`<ellipse cx="0" cy="60" rx="${fmt(170+10*Math.sin(t*4))}" ry="120" fill="#F2A541" opacity=".35"/>`:'';return g(`scale(${s})`,`${glow}<path d="M-60,-200L60,-200L60,40C60,80 120,90 150,100C190,115 185,170 140,175L-30,172C-70,170 -75,130 -60,110Z" fill="#F2C9A0" stroke="${OL}" stroke-width="7"/>${o.vessel?`<path d="M-20,-180C-10,-80 30,0 0,120M20,-170C40,-60 70,40 100,140" stroke="#E5383B" stroke-width="${o.wide?14:6}" fill="none" stroke-linecap="round" opacity=".8"/>`:''}`);}
function iceTea(t,s=1,sweet=1){let ice='';for(let i=0;i<4;i++)ice+=`<rect x="${-60+i*30}" y="${-60+((i*37)%40)}" width="40" height="40" rx="8" fill="#fff" opacity=".7" transform="rotate(${i*15+Math.sin(t*2+i)*5})"/>`;
 return g(`scale(${s})`,`<path d="M-110,-160L110,-160L85,190L-85,190Z" fill="#C8792E" stroke="${OL}" stroke-width="8" opacity=".95"/>${ice}<path d="M-110,-160L110,-160" stroke="${OL}" stroke-width="8"/><path d="M40,-260L10,120" stroke="#E5383B" stroke-width="16" stroke-linecap="round"/><path d="M-80,160L80,160" stroke="#fff" stroke-width="18" opacity="${fmt(0.5*sweet)}"/><ellipse cx="-60" cy="-60" rx="12" ry="60" fill="#fff" opacity=".25"/>`);}
